<?php
require_once __DIR__.'/../../config/database.php';
require_once __DIR__.'/../../includes/session.php';
require_once __DIR__.'/../../includes/functions.php';
require_once __DIR__.'/../../includes/admin_layout.php';
if(!is_admin_logged_in())redirect('../../index.php');

function participant_password($length=14){$chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%';$out='';for($i=0;$i<$length;$i++)$out.=$chars[random_int(0,strlen($chars)-1)];return $out;}
function generation_campaign($conn,$id){$r=pg_query_params($conn,"SELECT id,title,status FROM feedback_campaigns WHERE id=$1 AND status='draft'",[$id]);return $r&&pg_num_rows($r)===1?pg_fetch_assoc($r):null;}
function next_participant_number($conn,$campaignId,$prefix){$r=pg_query_params($conn,"SELECT participant_code FROM feedback_participants WHERE participant_code LIKE $1 ORDER BY id DESC LIMIT 1",[$prefix.'-%']);if(!$r||pg_num_rows($r)===0)return 1;$parts=explode('-',pg_fetch_result($r,0,0));return max(1,(int)end($parts)+1);}
function insert_participant_batch($conn,$campaign,$prefix,$records){$generated=[];$next=next_participant_number($conn,(int)$campaign['id'],$prefix);if(!pg_query($conn,'BEGIN'))return false;try{foreach($records as $record){do{$code=$prefix.'-'.str_pad($next++,4,'0',STR_PAD_LEFT);$exists=pg_query_params($conn,'SELECT 1 FROM feedback_participants WHERE lower(participant_code)=lower($1)',[$code]);}while($exists&&pg_num_rows($exists)>0);$password=participant_password();$ok=pg_query_params($conn,'INSERT INTO feedback_participants(campaign_id,participant_code,full_name,group_name,password_hash) VALUES($1,$2,$3,$4,$5)',[(int)$campaign['id'],$code,$record['name'],$record['group'],password_hash($password,PASSWORD_DEFAULT)]);if(!$ok)throw new RuntimeException('Insert failed');$generated[]=['campaign'=>$campaign['title'],'code'=>$code,'password'=>$password,'name'=>$record['name'],'group'=>$record['group']];}if(!pg_query($conn,'COMMIT'))throw new RuntimeException('Commit failed');return $generated;}catch(Throwable $e){pg_query($conn,'ROLLBACK');return false;}}

$campaigns=pg_query($conn,"SELECT id,title,status FROM feedback_campaigns WHERE status='draft' ORDER BY created_at DESC");$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verify_csrf_token($_POST['csrf_token']??''))$error='Security token expired. Please refresh and try again.';else{
  $campaignId=(int)($_POST['campaign_id']??0);$campaign=generation_campaign($conn,$campaignId);$prefix=strtoupper(preg_replace('/[^A-Za-z0-9]/','',trim($_POST['prefix']??'PART')));$prefix=$prefix?:'PART';
  if(!$campaign)$error='Select a draft campaign. Account generation is locked after the campaign starts.';elseif(!verify_admin_password($conn,$_SESSION['admin_id'],$_POST['admin_password']??''))$error='Correct administrator password is required.';else{
   $records=[];$method=$_POST['action']??'bulk';
   if($method==='bulk'){$count=(int)($_POST['count']??0);$group=trim($_POST['group_name']??'');if($count<1||$count>100)$error='Enter an account count from 1 to 100.';else for($i=1;$i<=$count;$i++)$records[]=['name'=>'Participant '.$i,'group'=>$group];}
   elseif($method==='csv'){if(!isset($_FILES['csv_file'])||$_FILES['csv_file']['error']!==UPLOAD_ERR_OK)$error='Select a valid CSV file.';elseif($_FILES['csv_file']['size']>2097152)$error='CSV file must be 2 MB or smaller.';else{$handle=fopen($_FILES['csv_file']['tmp_name'],'r');if($handle){$first=true;while(($row=fgetcsv($handle))!==false){if($first){$first=false;if(strtolower(trim($row[0]??''))==='full_name')continue;}$name=trim($row[0]??'');if($name==='')continue;$records[]=['name'=>mb_substr($name,0,180),'group'=>mb_substr(trim($row[1]??''),0,120)];if(count($records)>=500)break;}fclose($handle);}if(!$records)$error='No valid participant rows were found.';}}
   else $error='Invalid generation method.';
   if(!$error){$generated=insert_participant_batch($conn,$campaign,$prefix,$records);if($generated===false)$error='Participant accounts could not be generated.';else{$_SESSION['generated_participant_credentials']=$generated;audit_log($conn,'feedback_participants_generated','feedback_campaign',$campaignId,['count'=>count($generated),'method'=>$method]);redirect('credentials.php');}}
  }
 }
}
admin_page_start('Generate Participant Accounts','participants');?>
