<div class="grid two-col"><div class="card"><h3><i class="fa-solid fa-users-gear"></i> Bulk generation</h3><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="bulk"><div class="field full"><label>Draft campaign</label><select name="campaign_id" required><option value="">Select campaign…</option><?php if($campaigns):while($c=pg_fetch_assoc($campaigns)):?><option value="<?=(int)$c['id']?>" <?=((int)($_GET['campaign_id']??0)===(int)$c['id'])?'selected':''?>><?=h($c['title'])?></option><?php endwhile;pg_result_seek($campaigns,0);endif;?></select></div><div class="field"><label>ID prefix</label><input name="prefix" value="PART" maxlength="12" required></div><div class="field"><label>Number of accounts</label><input type="number" name="count" min="1" max="100" value="10" required></div><div class="field full"><label>Group / department</label><input name="group_name" placeholder="Optional shared group"></div><div class="field full"><label>Confirm administrator password</label><input type="password" name="admin_password" required autocomplete="current-password"></div><div class="field full"><button class="btn"><i class="fa-solid fa-key"></i> Generate accounts</button></div></form></div>
<div class="card"><h3><i class="fa-solid fa-file-csv"></i> Import participant names</h3><p class="help">Upload a CSV with columns <strong>full_name</strong> and <strong>group_name</strong>. Up to 500 records per import.</p><form method="post" enctype="multipart/form-data" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="csv"><div class="field full"><label>Draft campaign</label><select name="campaign_id" required><option value="">Select campaign…</option><?php if($campaigns):while($c=pg_fetch_assoc($campaigns)):?><option value="<?=(int)$c['id']?>" <?=((int)($_GET['campaign_id']??0)===(int)$c['id'])?'selected':''?>><?=h($c['title'])?></option><?php endwhile;endif;?></select></div><div class="field"><label>ID prefix</label><input name="prefix" value="PART" maxlength="12" required></div><div class="field"><label>CSV file</label><input type="file" name="csv_file" accept=".csv,text/csv" required></div><div class="field full"><label>Confirm administrator password</label><input type="password" name="admin_password" required autocomplete="current-password"></div><div class="field full actions"><button class="btn"><i class="fa-solid fa-upload"></i> Import and generate</button><a class="btn secondary" href="template.php"><i class="fa-solid fa-download"></i> CSV template</a></div></form></div></div>
<?php admin_page_end();?>
